const circs = []; // array of circs
const num = 2;    // num of eyes
const clrs = ["red", "green", "blue"]; // add for more inner circs
const autoUpdateNumRays = false; // change if you want

function setup() {
  createCanvas(windowWidth, windowHeight);
  background(32);

  strokeWeight(2);
  stroke(127);

	// insert 2 "eyes"
  for (let n = 0; n < num; n++) {
    insertEye(((n + 1) * width) / (num + 1), height / 2, width / (num + 1), clrs, n % 2 !== 0);
  }

  frameRate(30);
}

function insertEye(x, y, r, clrs, backwards) {
	// create structure circ for inner rays, will not be displayed later
  circs.push(new Circ(x, y, r * 0.05, clrs.length)); // clrs.length anchor positions
  if (backwards) circs[circs.length-1].da = -circs[circs.length-1].da;
  const poss = circs[circs.length - 1].getPos();

	// for every anchor position
  for (let i = 0; i < poss.length; i++) {
    const p1 = poss[i];
    const p2 = poss[(i + 1) % poss.length];
    const p = { x: lerp(p1.x, p2.x, 0.5), y: lerp(p1.y, p2.y, 0.5) };
		// create again rotating structure circ
    circs.push(new Circ(p.x, p.y, r * 0.05, clrs.length));
    if (backwards) circs[circs.length-1].da = -circs[circs.length-1].da;
    circs[circs.length - 1].a = -TWO_PI / poss.length + (TWO_PI * i) / poss.length;
    const cp = circs[circs.length - 1].getPos();
		// create circ to visuaklize with num of rays and given color
    circs.push(new Circ(cp[0].x, cp[0].y, r * 0.4, 17, clrs[i]));
    if (backwards) circs[circs.length-1].da = -circs[circs.length-1].da;
  }
}

function draw() {
  blendMode(BLEND);
  background(32);

  push();
  blendMode(ADD);
  const per_n = circs.length / num;
  for (let n = 0; n < num; n++) {
    for (let i = 1; i < per_n; i += 2) {
      const sc = circs[n * per_n + i]; // structure circle
      var poss = sc.getPos();
      sc.update();

      const dc = circs[n * per_n + i + 1]; // display circ
      dc.show();
      dc.update(poss[0].x, poss[0].y);
			if (autoUpdateNumRays) {
				dc.setNumAnchors(20 + 10 * sin(TWO_PI * floor(fract(frameCount/40)*10)/10)); 
			} else {
				if ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) && (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))) dc.setNumAnchors(map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 3, 40), map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, 200, 2));
			}
    }
  }
  pop();
  // // noLoop() removed for animation
}


function mousePressed() {
  if (mouseButton === LEFT) {
    loop();
  }
}

// Class Circ
// define position and size and num of anchor points
// get positions of anchors after update() and getPos()
class Circ {
  constructor(x, y, r, n, clr = null) {
    this.x = x;
    this.y = y;
    this.r = r;
    this.n = n;
    this.a = 0;
    this.da = TWO_PI / n / 16; // level of detail rotation > 1
    this.clr = clr || color(128);
  }

	setNumAnchors(n, t = 16) {
		n = floor(n);
		this.n = n;
		this.da = TWO_PI / n / t * Math.sign(this.da);
	}

  getPos(n = null) {
    var poss = [];
    if (!n) n = this.n;

    for (let i = 0; i < n; i++) {
      const ca = (i / n) * TWO_PI;
      const x = cos(this.a + ca) * this.r + this.x;
      const y = sin(this.a + ca) * this.r + this.y;
      poss.push({ x, y });
    }

    return poss;
  }

  update(x = null, y = null) {
    // console.log("circ.update("+x+", "+y+")")
    this.a += this.da;
    if (!(x === null || y === null)) {
      this.x = x;
      this.y = y;
    }
  }

  show() {
    push();
    noFill();
    stroke(this.clr);
    translate(this.x, this.y);
    rotate(this.a);

    // circle(0, 0, this.r * 2);
    // strokeWeight(2);
    // line(0, -this.r, 0, this.r);

    noStroke();
    fill(this.clr);
    var poss = this.getPos(this.n * 2);
    for (let i = 0; i < poss.length - 1; i += 2) {
      beginShape();
      vertex(0, 0);
      vertex(poss[i].x - this.x, poss[i].y - this.y);
      vertex(poss[i + 1].x - this.x, poss[i + 1].y - this.y);
      endShape(CLOSE);
    }

    pop();
  }
}
